    async function initMockDb() {   
    window.LOCAL_DB = JSON.parse(JSON.stringify(EMBEDDED_SEED));  
    const meters = window.LOCAL_DB.METERS || [];
    const abonents = window.LOCAL_DB.ABONENTS || [];
    const controllers = window.LOCAL_DB.CONTROLLERS || [];
    const validControllerIds = controllers.map(c => c.ID);
    meters.forEach((m, i) => {
      if (!m.CONTROLER_ID || m.CONTROLER_ID === 0 || !validControllerIds.includes(m.CONTROLER_ID)) {
        m.CONTROLER_ID = validControllerIds[i % validControllerIds.length];
      }
    });
    meters.forEach((m, i) => {
      const abonent = abonents[i % abonents.length];
      if (abonent && abonent.G_LICSCHET) {
        m.LS = abonent.G_LICSCHET;
      }
    });
    const buildingMetersMap = {};  
    meters.forEach(meter => {
      const ls = String(meter.LS || '').trim();
      if (!ls) return;     
      const abonent = abonents.find(a => String(a.G_LICSCHET || '').trim() === ls);
      if (!abonent) return;    
      const buildingId = abonent.BUILDING_ID || abonent.BUILDINGS_ID;
      if (!buildingId) return;    
      if (!buildingMetersMap[buildingId]) {
        buildingMetersMap[buildingId] = [];
      }
      buildingMetersMap[buildingId].push(meter);
    });
    window.LOCAL_DB.BUILDINGS_METERS = [];
    let bmIdCounter = 10000;
    Object.entries(buildingMetersMap).forEach(([buildingId, buildingMeters]) => {
      const count = buildingMeters.length;
      let serviceIds = [];
      if (count === 1) {
        serviceIds = [537];
      } else if (count === 2) {
        serviceIds = [555, 597];
      } else {
        serviceIds = [555, 597, 537];
      }   
      buildingMeters.forEach((meter, idx) => {
        const groupId = serviceIds[idx % serviceIds.length];     
        window.LOCAL_DB.BUILDINGS_METERS.push({
          ID: bmIdCounter++,
          BUILDING_ID: Number(buildingId),
          GROUP_ID: groupId,
          METER_ID: Number(meter.ID),
          CREATEUSERID: 1,
          CREATEDATE: '2026-01-01',
          APPARTS: String(abonents.find(a => String(a.G_LICSCHET || '').trim() === String(meter.LS))?.APPARTS || '')
        });
      });
    });
    if (!window.LOCAL_DB.BOILER_STATUS) {
      window.LOCAL_DB.BOILER_STATUS = [];
    }
    Object.entries(buildingMetersMap).forEach(([bid, ms]) => {
      const count = ms.length;
      const services = count === 1 ? 'Отопление' : count === 2 ? 'ХВС + ГВС' : 'ХВС + ГВС + Отопление';
    });
    window.MOCK_DB_READY = true;
    resolveMockDb();    
  }
  initMockDb();
  function clone(obj) {
    return JSON.parse(JSON.stringify(obj));
  }
  function loadDb() {
    return window.LOCAL_DB ? clone(window.LOCAL_DB) : {};
  }
  function persistDb() {
    if (!LOCAL_MOCK_PERSIST || !window.LOCAL_DB) return;
    try {
      localStorage.setItem(LOCAL_DB_KEY, JSON.stringify(window.LOCAL_DB));
    } catch (e) {
      if (e.name !== 'QuotaExceededError') {
        console.warn('Не удалось сохранить изменения:', e);
      }
    }
  }

  window.resetLocalMockDb = function () {
    try {
      localStorage.removeItem(LOCAL_DB_KEY);
    } catch (e) {
      console.log('error: ', e);
    }
    window.location.reload();
  };

  function httpResponse(status, body) {
    return {
      __localResponse: true,
      status,
      body
    };
  }

  function toNumber(value) {
    if (value === null || value === undefined || value === '') {
      return null;
    }
    const n = Number(value);
    return isNaN(n) ? null : n;
  }

  function formatDateOnly(d) {
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }

  function nowDateTime() {
    const d = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  }

  function nextId(tableName) {
    const arr = window.LOCAL_DB?.[tableName] || [];
    return arr.reduce((max, row) => Math.max(max, toNumber(row.ID) || 0), 0) + 1;
  }

  function getAbonentByLs(ls) {
    const normalizedLs = String(ls ?? '').trim();
    return window.LOCAL_DB?.ABONENTS?.find(
      a => String(a.G_LICSCHET ?? a.LS ?? '').trim() === normalizedLs
    ) || null;
  }

  function getClientByLs(ls) {
    const abonent = getAbonentByLs(ls);
    if (!abonent) return null;
    return window.LOCAL_DB?.CLIENTS?.find(
      c => String(c.ID) === String(abonent.CLIENT_ID)
    ) || null;
  }

  function getAbonentByMeter(meter) {
    if (!meter) return null;
    const meterLs = String(meter.LS || meter.G_LICSCHET || '').trim();
    if (meterLs && meterLs !== 'null') {
      const byLs = (window.LOCAL_DB?.ABONENTS || []).find(
        a => String(a.G_LICSCHET || a.LS || '').trim() === meterLs
      );
      if (byLs) return byLs;
    }
    const link = (window.LOCAL_DB?.BUILDINGS_METERS || []).find(
      row => String(row.METER_ID) === String(meter.ID)
    );
    if (!link) return null;
    const buildingId = link.BUILDING_ID || link.BUILDINGS_ID;
    if (!buildingId) return null;
    const candidates = (window.LOCAL_DB?.ABONENTS || []).filter(
      abonent => String(abonent.BUILDING_ID || abonent.BUILDINGS_ID) === String(buildingId)
    );
    if (candidates.length === 0) return null;
    const linkApparts = String(link.APPARTS || '').trim();
    if (linkApparts && linkApparts !== '') {
      const exactMatch = candidates.find(
        abonent => String(abonent.APPARTS || '').trim() === linkApparts
      );
      if (exactMatch) return exactMatch;
    }
    return null;
  }

  function getServiceByMeter(meter) {
    if (!meter) return null;
    const buildingMeter = (window.LOCAL_DB?.BUILDINGS_METERS || []).find(
      row => String(row.METER_ID) === String(meter.ID)
    );
    if (!buildingMeter) {
      const abonent = getAbonentByMeter(meter);
      if (abonent) {
        const buildingId = abonent.BUILDING_ID || abonent.BUILDINGS_ID;
        const fallbackLink = (window.LOCAL_DB?.BUILDINGS_METERS || []).find(
          row => String(row.BUILDING_ID) === String(buildingId)
        );
        if (fallbackLink) {
          return window.LOCAL_DB?.SERVICES?.find(
            service => String(service.ID) === String(fallbackLink.GROUP_ID)
          ) || null;
        }
      }
      return null;
    }
    return window.LOCAL_DB?.SERVICES?.find(
      service => String(service.ID) === String(buildingMeter.GROUP_ID)
    ) || null;
  }

  function getServiceNamesByMeter(meter) {
    if (!meter) return ['Услуга не указана'];
    let buildingMeters = (window.LOCAL_DB?.BUILDINGS_METERS || []).filter(
      row => String(row.METER_ID) === String(meter.ID)
    );
    if (buildingMeters.length === 0) {
      const abonent = getAbonentByMeter(meter);
      if (abonent) {
        const buildingId = abonent.BUILDING_ID || abonent.BUILDINGS_ID;
        buildingMeters = (window.LOCAL_DB?.BUILDINGS_METERS || []).filter(
          row => String(row.BUILDING_ID) === String(buildingId)
        );
      }
    }
    const serviceIds = [...new Set(
      buildingMeters.map(row => String(row.GROUP_ID)).filter(id => id && id !== 'undefined' && id !== 'null')
    )];
    if (serviceIds.length === 0) return ['Услуга не указана'];
    const services = serviceIds.map(id => {
      const service = (window.LOCAL_DB?.SERVICES || []).find(s => String(s.ID) === id || String(s.GROUP_ID) === id);
      return service ? (service.GROUP_NAME || service.SHORT_NAME || service.NAME) : 'Неизвестная услуга';
    });
    const uniqueServices = [...new Set(services)];
    const order = { 
      'Холодное водоснабжение': 1, 'ХВС': 1, 
      'Горячее водоснабжение': 2, 'ГВС': 2, 'ХВС на ГВС': 2,
      'Отопление': 3 
    };
    uniqueServices.sort((a, b) => (order[a] || 99) - (order[b] || 99));
    return uniqueServices.length > 0 ? uniqueServices : ['Услуга не указана'];
  }

  function isValidMeter(meter) {
    if (toNumber(meter.STATUS) !== 1) {
      return false;
    }
    const service = getServiceByMeter(meter);
    if (!service) {
      return true;
    }
    return [537, 555, 597].includes(toNumber(service.ID)) ||
      [537, 555, 597].includes(toNumber(service.GROUP_ID));
  }

  function getFirstControllerIdByLs(ls, preferredControllerId = null) {
    const meters = window.LOCAL_DB?.METERS?.filter(
      m => String(m.LS) === String(ls)
    ) || [];

    if (!meters.length) {
      return null;
    }

    const sorted = [...meters].sort((a, b) => {
      const aCtrl = toNumber(a.CONTROLER_ID);
      const bCtrl = toNumber(b.CONTROLER_ID);
      const aPreferred = preferredControllerId !== null && aCtrl === preferredControllerId ? 1 : 0;
      const bPreferred = preferredControllerId !== null && bCtrl === preferredControllerId ? 1 : 0;
      if (aPreferred !== bPreferred) {
        return bPreferred - aPreferred;
      }
      if (aCtrl === null && bCtrl === null) return 0;
      if (aCtrl === null) return 1;
      if (bCtrl === null) return -1;
      return bCtrl - aCtrl;
    });
    return toNumber(sorted[0].CONTROLER_ID);
  }

  function compareByControllerIdDesc(a, b) {
    const aCtrl = toNumber(a.controllerId);
    const bCtrl = toNumber(b.controllerId);
    if (aCtrl === null && bCtrl === null) return 0;
    if (aCtrl === null) return 1;
    if (bCtrl === null) return -1;
    return bCtrl - aCtrl;
  }

  function meterToListItem(meter) {
    const abonent = getAbonentByMeter(meter);
    const client = abonent
      ? window.LOCAL_DB?.CLIENTS?.find(c => String(c.ID) === String(abonent.CLIENT_ID))
      : null;
    const service = getServiceByMeter(meter);
    return {
      found: true,
      id: meter.ID,
      meterNum: meter.METER_NUM,
      name: meter.NAME || '',
      seal: meter.SEAL || '',
      manfDate: meter.MANFDATE || null,
      mountDate: meter.MOUNT_DATE,
      verifyDate: meter.VERIFY_DATE,
      licschet: meter.LS,
      apparts: abonent ? (abonent.APPARTS || null) : null,
      groupName: service
        ? (service.GROUP_NAME || service.NAME || service.SHORT_NAME || null)
        : null,
      clientName: client ? (client.NAME || null) : null
    };
  }

  function sortMetersByMountDateDesc(list) {
    return list.sort((a, b) => {
      return String(b.mountDate || '').localeCompare(String(a.mountDate || ''));
    });
  }

