    '/apparts': ({ query }) => {
      const buildingId = toNumber(query.buildingId);
      const controllerId = toNumber(query.controllerId);
      const abonents = (window.LOCAL_DB?.ABONENTS || []).filter(a =>
        toNumber(a.BUILDING_ID ?? a.BUILDINGS_ID) === buildingId
      );
      const result = [];
      abonents.forEach(abonent => {
        const metersByLs = (window.LOCAL_DB?.METERS || []).filter(m => String(m.LS || m.G_LICSCHET) === String(abonent.G_LICSCHET));
        let include = metersByLs.length === 0 || metersByLs.some(m => toNumber(m.CONTROLER_ID) === controllerId && isValidMeter(m));
        if (!include) return;
        const letterPart = abonent.LETTER ? ` ${abonent.LETTER}` : '';
        const house = !abonent.APPARTS || String(abonent.APPARTS).trim() === '' ? letterPart.trim() : `кв. ${abonent.APPARTS}${letterPart}`.trim();
        result.push({
          id: abonent.ID, house, g_licschet: abonent.G_LICSCHET,
          controllerId: getFirstControllerIdByLs(abonent.G_LICSCHET, controllerId),
          _apparts: abonent.APPARTS || '', _letter: abonent.LETTER || ''
        });
      });
      result.sort((a, b) => compareByControllerIdDesc(a, b) || String(a._apparts ?? '').localeCompare(String(b._apparts ?? ''), 'ru', { numeric: true }) || String(a._letter ?? '').localeCompare(String(b._letter ?? ''), 'ru'));
      return result.map(({ _apparts, _letter, ...rest }) => rest);
    },

